tokens.css:
--color-bg: #faf7f2;
--color-surface: #f3eee4;
--color-text: #2b2621;
--color-text-muted: #6e655a;
--color-border: #e2dacb;
--color-primary: #13aff0;
--color-on-primary: #101418;
--color-accent: #5f7a4a;
--color-on-accent: #ffffff;
--font-display: "Fraunces", Georgia, serif;
--font-body: "Work Sans", system-ui, sans-serif;
--text-sm: 13px;
--text-base: 16px;
--text-lg: 20px;
--text-xl: 25px;
--text-2xl: 31px;
--text-3xl: 39px;
--radius-control: 6px;
--radius-card: 12px;
--space-section: 120px;
--shadow-card: 0 1px 2px color-mix(in oklab, var(--color-text) 8%, transparent), 0 10px 30px color-mix(in oklab, var(--color-text) 12%, transparent);
